from pathlib import Path
import json,hashlib
D=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
r=json.loads((D/'body-routes.json').read_text());check=json.loads((D/'body-route-static.json').read_text());assert check['complete'] and check['passedStatic']
for p,h in check['sourceHashes'].items():assert sha(p)==h,p
parts=[]
for x in r['parts']:
 if not x['key'].startswith('power_'):continue
 rb=next(v for v in check['readback'] if v['key']==x['key'])
 parts.append({'key':x['key'],'name':'Paired5V body corridor: '+x['net'],'file':x['nativeStep'],'sha256':sha(x['nativeStep']),'format':'STEP','units':'mm','coordinates':'world mm, no added transform','meshFile':x['file'],'meshSha256':sha(x['file']),'expectedFinalBoundsMm':rb['boundsMm'],'color':'#d74239' if x['net']=='5V' else '#292929','group':'DFR-to-neck body corridor only','centerlineSections':x['routeSections'],'diameterReceivingMm':x['diameterMm'],'bendRadiusMm':x['minimumBendRadiusMm'],'lengthMm':x['lengthMm'],'fromReceivingInterfaceWorldMm':x['from'],'freeEndWorldMm':x['toFreeNeckBoundary'],'sourceSolderTerminationModeled':False})
gaps=[q for q in check['rows'] if 'minimumMeshGapWithin1mm' in q]
m={'title':'Original-body paired power corridor, wall-supply architecture','parts':parts,'scope':'Insulated conductor receiving corridor only, from2mm beyond DFR top edge through original vent and asymmetric upper bracket notch to a free neck-root boundary. It is not an electrically complete feed.','staticPathGeometryAccepted':True,'completeElectricalConnectionAccepted':False,'sourceTopology':'Existing wall charger→5991→DFR1202; do not revive the withdrawnPB1033MI or11-fuse array.','sourceRegistration':str(D/'dfr1202-terminal-registration.json'),'requiredActualContactsNotYetInstalled':['DFR VOUT and GND solder joins to the initial receiving interfaces; the existing CAD part is only a30x26x8mm envelope, not PCB-pad geometry.','Actual insulated star splice/distribution point and its branch mapping. No fabricated terminal board or extra connector is included.','Head-side receiving connection after the accepted head layout; these free ends are not fixed on a moving link.'],'currentSupplyDiameterBoundary':'3.2mm external-diameter receiving envelope for the contract16AWG pair. Does not certify stocked insulation diameter, current rating, solder construction or source protection.','interferenceReceipt':{'file':str(D/'body-route-static.json'),'sha256':sha(D/'body-route-static.json'),'expectedPairs':check['expectedPairs'],'complete':check['complete'],'knownIntersections':0},'gaps':gaps,'minimumMeasuredMeshGapMm':min(q['minimumMeshGapWithin1mm'] for q in gaps),'clearanceMeaning':'Nominal geometry only;0.185mm closest gap is not a0.5mm manufacturing allowance. No plastic cut or wire diameter reduction was used to pass.','geometryChanges':'No torso, regulator insert, hip or leg changes. IMU holder/cover are a separately accepted local component.','assemblySequence':['Solder and insulate the DFR leads with the converter outside its open insert.','Seat the converter with its power-pad edge upward. Exact pad lead geometry remains to be registered before declaring the feed complete.','Guide the pair through the original negative-Y top vent, over the existing upper-hook lip and inside the asymmetric notch.','Retain the fixed segment using the existing support tie provisions after the actual splice and tie arrangement is selected; do not tie across a solder pad or thermal-pad area.','Leave the neck-root ends free for the final head cable/slack arrangement.'],'physicalFitVerified':False,'wholeHarnessAccepted':False,'sourceHashes':{str(D/f):sha(D/f) for f in ['body-routes.json','body-route-static.json','dfr1202-terminal-registration.json','structural-sections.png','write_power_manifest.py']}}
(D/'power-body-manifest.json').write_text(json.dumps(m,indent=2)+'\n');print(json.dumps({'file':str(D/'power-body-manifest.json'),'sha256':sha(D/'power-body-manifest.json'),'minGap':m['minimumMeasuredMeshGapMm']}))
